import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Policies_of_the_hotel import Get_Policies_of_the_hotel

import traceback

# --- Constants ---
TARGET_LOCATION = "Co-op City"
CHECKIN_DATE = "2026-06-20"
CHECKOUT_DATE = "2026-06-25"
DEST_ORDER_BY = "popularity"
ROOM_NUMBER = 1
CURRENCY = "USD"
CANCELLATION_KEYWORD = "flexible"

def get_location_id(location_name):
    """
    Searches for the location and returns the dest_id and dest_type.
    """
    try:
        results = Search_locations(name=location_name)
        if not results or not isinstance(results, list):
            return None, None

        # Prioritize 'city' type as per user requirement "hotels in Co-op City"
        for loc in results:
            if loc.get("dest_type") == "city":
                return loc.get("dest_id"), loc.get("dest_type")

        # Fallback to the first result if no city type is found
        first = results[0]
        return first.get("dest_id"), first.get("dest_type")
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

def get_hotels_list(dest_id, dest_type):
    """
    Retrieves the list of hotels for the given destination.
    """
    try:
        response = Search_hotels(
            checkin_date=CHECKIN_DATE,
            checkout_date=CHECKOUT_DATE,
            dest_type=dest_type,
            dest_id=dest_id,
            order_by=DEST_ORDER_BY,
            room_number=ROOM_NUMBER,
            filter_by_currency=CURRENCY
        )
        if isinstance(response, dict) and "result" in response:
            return response.get("result", [])
        return []
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

def check_if_flexible_cancellation(hotel):
    """
    Checks if a hotel has a flexible cancellation policy.
    Uses both the search result flag and the detailed policy API.
    """
    # First check the quick flag from Search_hotels response schema
    if hotel.get("is_free_cancellable") == 1:
        return True

    # Second check: Detailed Policies API
    hotel_id = hotel.get("hotel_id")
    if not hotel_id:
        return False

    try:
        policy_data = Get_Policies_of_the_hotel(hotel_id=hotel_id)
        if not policy_data or "policy" not in policy_data:
            return False

        # Traverse the response_schema: policy (array) -> content (array) -> ruleset (array) -> rule (array) -> content (string)
        for p_item in policy_data.get("policy", []):
            for content_item in p_item.get("content", []):
                for rs in content_item.get("ruleset", []):
                    for rule in rs.get("rule", []):
                        rule_text = rule.get("content", "").strip().lower().replace('®', '').replace('™', '').replace('©', '')
                        if CANCELLATION_KEYWORD.strip().lower() in rule_text:
                            return True
    except Exception:
        # Log error but don't crash; treat as not found for this specific hotel
        pass

    return False

def calculate_flexible_proportion():
    """
    Orchestrates the flow to find the proportion of flexible hotels.
    """
    dest_id, dest_type = get_location_id(TARGET_LOCATION)
    if not dest_id:
        raise Exception(f"Could not find location details for {TARGET_LOCATION}.")

    hotels = get_hotels_list(dest_id, dest_type)
    total_hotels = len(hotels)

    if total_hotels == 0:
        raise Exception(f"No hotels found in {TARGET_LOCATION}.")

    flexible_count = 0
    for hotel in hotels:
        if check_if_flexible_cancellation(hotel):
            flexible_count += 1

    proportion = flexible_count / total_hotels
    print(f"Total hotels found in {TARGET_LOCATION}: {total_hotels}")
    print(f"Hotels with flexible cancellation: {flexible_count}")
    print(f"Proportion of hotels with flexible cancellation policy: {proportion:.2%}")

if __name__ == "__main__":
    try:
        calculate_flexible_proportion()
    except Exception:
        traceback.print_exc(file=sys.stderr)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Hotel_data import Get_Hotel_data

import traceback
import os
import requests
from datetime import datetime, date

# --- API calling code (Black Box) ---
def Search_locations(name):
    url = "https://booking-com.p.rapidapi.com/v1/hotels/locations"
    rapid_api_key = os.getenv('RAPID_API_KEY')
    querystring = {"name": name, "locale": "en-us"}
    headers = {"x-rapidapi-key": rapid_api_key, "x-rapidapi-host": "booking-com.p.rapidapi.com"}
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

def Search_hotels(checkin_date, checkout_date, dest_type, dest_id, order_by, room_number, filter_by_currency):
    url = "https://booking-com.p.rapidapi.com/v1/hotels/search"
    rapid_api_key = os.getenv('RAPID_API_KEY')
    querystring = {
        "adults_number": 2,
        "units": "metric",
        "checkin_date": checkin_date,
        "checkout_date": checkout_date,
        "dest_type": dest_type,
        "dest_id": dest_id,
        "order_by": order_by,
        "room_number": room_number,
        "filter_by_currency": filter_by_currency,
        "locale": "en-us"
    }
    headers = {"x-rapidapi-key": rapid_api_key, "x-rapidapi-host": "booking-com.p.rapidapi.com"}
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        return {"error": f"Request failed with status code {response.status_code}"}

def Get_Hotel_data(hotel_id):
    url = "https://booking-com.p.rapidapi.com/v1/hotels/data"
    rapid_api_key = os.getenv('RAPID_API_KEY')
    querystring = {"hotel_id": hotel_id, "locale": "en-us"}
    headers = {"x-rapidapi-key": rapid_api_key, "x-rapidapi-host": "booking-com.p.rapidapi.com"}
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

# --- Logic ---

def get_location_id(location_name):
    results = Search_locations(name=location_name)
    if not results or not isinstance(results, list):
        raise Exception("No location results found")

    for loc in results:
        # C4: Normalization for comparison
        name_val = loc.get("name", "").strip().lower().replace("®", "").replace("™", "").replace("©", "")
        query_val = location_name.strip().lower().replace("®", "").replace("™", "").replace("©", "")
        if query_val in name_val:
            return loc.get("dest_id"), loc.get("dest_type")

    return results[0].get("dest_id"), results[0].get("dest_type")

def get_expensive_properties(dest_id, dest_type, checkin, checkout, order_by, room_num, currency):
    response = Search_hotels(
        checkin_date=checkin,
        checkout_date=checkout,
        dest_type=dest_type,
        dest_id=dest_id,
        order_by=order_by,
        room_number=room_num,
        filter_by_currency=currency
    )
    if not response or "result" not in response:
        return []
    return response.get("result", [])

def check_if_entire_home(hotel_id):
    details = Get_Hotel_data(hotel_id=hotel_id)
    if not details:
        return False

    bh = details.get("booking_home", {})
    if bh.get("is_vacation_rental") == 1 or bh.get("is_booking_home") == 1:
        return True

    name = details.get("name", "").strip().lower().replace("®", "").replace("™", "").replace("©", "")
    if "entire home" in name or "apartment" in name:
        return True

    return False

def extract_nightly_price(property_data):
    breakdown = property_data.get("composite_price_breakdown", {})
    nightly_data = breakdown.get("gross_amount_per_night", {})
    return nightly_data.get("value"), nightly_data.get("currency")

def main():
    # C2: Hardcoded constants
    LOCATION_QUERY = "Kew Gardens"
    CHECKIN_DATE = "2026-06-20"
    CHECKOUT_DATE = "2026-06-21"
    ORDER_BY = "price"
    ROOM_NUMBER = 1
    CURRENCY = "USD"

    try:
        dest_id, dest_type = get_location_id(LOCATION_QUERY)
        if not dest_id:
            raise Exception(f"Could not find location ID for {LOCATION_QUERY}")

        properties = get_expensive_properties(
            dest_id, dest_type, CHECKIN_DATE, CHECKOUT_DATE, ORDER_BY, ROOM_NUMBER, CURRENCY
        )
        if not properties:
            raise Exception(f"No properties found in {LOCATION_QUERY}")

        sorted_props = sorted(
            properties, 
            key=lambda x: x.get("min_total_price", 0) if x.get("min_total_price") else 0, 
            reverse=True
        )

        for prop in sorted_props:
            hotel_id = prop.get("hotel_id")
            if not hotel_id:
                continue

            if check_if_entire_home(hotel_id):
                price, currency = extract_nightly_price(prop)
                if price is not None:
                    print(f"The most expensive entire home/apt in {LOCATION_QUERY} costs {price} {currency} per night.")
                    return

        raise Exception(f"No entire home/apartment found in {LOCATION_QUERY}.")

    except Exception:
        # C6: Top-level handler
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

