from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

# --- Constants ---
TARGET_BUSINESS_NAME = "Cutting Edge Upholstery Solutions"
TARGET_POSTAL_CODE = "33611"
REGION_CODE = "us"

def find_business_id():
    """
    Searches for the business using the name and postal code and extracts the business_id.
    """

    # Construct query combining name and postal code for better accuracy
    query = f"{TARGET_BUSINESS_NAME} {TARGET_POSTAL_CODE}"

    try:
        response = Search(query=query)

        # Rule 7: 200 + populated data is SUCCESS
        if response.get("status") == "OK" and response.get("data"):
            results = response.get("data", [])
            for business in results:
                # Rule 14: Lenient comparison for name and zipcode
                name = business.get("name", "")
                zipcode = business.get("zipcode", "")

                if TARGET_BUSINESS_NAME.lower() in name.lower() and TARGET_POSTAL_CODE in zipcode:
                    return business.get("business_id")

            # If no exact match in loop, return the first result as a fallback if it looks relevant
            if results:
                return results[0].get("business_id")

        return None
    except Exception as e:
        print(f"Error during business search: {e}")
        return None

def get_business_address(business_id):
    """
    Retrieves the address for a specific business_id.
    """
    if not business_id:
        return None

    try:
        response = Business_Details(business_id=business_id, region=REGION_CODE)

        if response.get("status") == "OK" and response.get("data"):
            # Rule 10: Extract EXACT key 'address' from response_schema
            business_data = response.get("data")[0]
            return business_data.get("address")

        return None
    except Exception as e:
        print(f"Error retrieving business details: {e}")
        return None

def main():
    """
    Orchestrates the flow to find the address of the target business.
    """
    try:
        business_id = find_business_id()
        if not business_id:
            print(f"Could not find a business ID for {TARGET_BUSINESS_NAME} in {TARGET_POSTAL_CODE}.")
            return

        address = get_business_address(business_id)
        if address:
            print(f"The address of {TARGET_BUSINESS_NAME} in area {TARGET_POSTAL_CODE} is: {address}")
        else:
            print(f"Could not retrieve the address for {TARGET_BUSINESS_NAME}.")

    except Exception:
        # Rule 9: Top-level exception handler printing full traceback to stderr
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

