from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

# --- Constants derived from user requirement
BUSINESS_NAME = "7-Eleven"
POSTAL_CODE = "37203"
SEARCH_QUERY = f"{BUSINESS_NAME} in {POSTAL_CODE}"
REGION_DEFAULT = "us"

def fetch_business_locations():
    """
    Searches for businesses based on the pinned query.
    Returns a list of business data objects.
    """
    try:
        # Rule 3: Construct correct inputs based on API_calling_code
        # Search(query)
        response = Search(query=SEARCH_QUERY)

        # Rule 7: API Success Criterion
        if response.get("status") == "OK":
            # Rule 10: Schema Grounding - extract 'data' key
            return response.get("data", [])
        return []
    except Exception:
        traceback.print_exc(file=sys.stderr)
        return []

def fetch_address_by_id(business_id):
    """
    Retrieves the address for a specific business ID.
    """
    try:
        # Rule 3: Construct correct inputs based on API_calling_code
        # Business_Details(business_id, region)
        response = Business_Details(business_id=business_id, region=REGION_DEFAULT)

        if response.get("status") == "OK":
            data_list = response.get("data", [])
            if data_list and len(data_list) > 0:
                # Rule 10: Schema Grounding - extract 'address' key
                return data_list[0].get("address")
        return None
    except Exception:
        traceback.print_exc(file=sys.stderr)
        return None

def orchestrate_search():
    """
    Main logic to find 7-Eleven addresses in the specified postal code.
    """
    businesses = fetch_business_locations()

    if not businesses:
        print(f"No {BUSINESS_NAME} locations found in area {POSTAL_CODE}.")
        return

    found_addresses = []
    for biz in businesses:
        # Rule 10: Schema Grounding - extract 'business_id'
        biz_id = biz.get("business_id")
        if biz_id:
            address = fetch_address_by_id(biz_id)
            if address:
                found_addresses.append(address)

    if found_addresses:
        print(f"Addresses of {BUSINESS_NAME} in {POSTAL_CODE}:")
        for addr in found_addresses:
            print(f"- {addr}")
    else:
        print(f"Could not retrieve specific addresses for {BUSINESS_NAME} in {POSTAL_CODE}.")

if __name__ == "__main__":
    try:
        orchestrate_search()
    except Exception:
        # Rule 9: Top-level exception handler
        traceback.print_exc(file=sys.stderr)

