import requests

def Search(query):
    """
    :API_description: This API performs location-based searches using a query string, with optional parameters to bias results towards specific geographic coordinates or regions.
    :param query: The search term for the local business.
    """
    url = "https://api.openwebninja.com/local-business-data/search"
    querystring = {
        "query": query,
    }
    headers = {
        "X-API-Key": "ak_p50mkprfx38u7h9pplfu0ukb3g0smunrabam7xed4rldpmb"
        }
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

def Business_Details(business_id, region):
    """
    :API_description: Retrieves comprehensive business profile information from Google Maps or Google Business, including contact details, operational hours, location data, reviews, and photos.
    :param business_id: The unique identifier for the business.
    :param region: The region where the business is located(e.g., "us").
    """
    url = "https://api.openwebninja.com/local-business-data/business-details"
    querystring = {
        "business_id": business_id,
        "region": region
    }
    headers = {
        "X-API-Key": "ak_p50mkprfx38u7h9pplfu0ukb3g0smunrabam7xed4rldpmb"
        }
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

# --- Logic Implementation ---

def find_business_identifier(query):
    """
    Searches for the business and extracts the business_id.
    """
    response = Search(query=query)
    if response.get("status") == "OK":
        data_list = response.get("data", [])
        if data_list:
            # Return the business_id of the first result
            return data_list[0].get("business_id")
    raise Exception(f"Could not find a business ID for query: {query}")

def get_business_location(business_id, region):
    """
    Retrieves business details and extracts the city.
    """
    response = Business_Details(business_id=business_id, region=region)
    if response.get("status") == "OK":
        data_list = response.get("data", [])
        if data_list:
            # Extract 'city' verbatim from response_schema
            return data_list[0].get("city")
    raise Exception(f"Could not determine the city for business_id: {business_id}")

def main():
    """
    Orchestrates the flow to find the city of the specified barber shop.
    """
    # C2: Task parameters hardcoded as named constants
    SEARCH_QUERY = "Francis The Duke Barber Co. PA"
    REGION_CODE = "us"

    # Step 1: Find the business ID
    business_id = find_business_identifier(SEARCH_QUERY)

    # Step 2: Get the city using the business ID
    city = get_business_location(business_id, REGION_CODE)

    if city:
        print(f"Francis The Duke Barber Co. is located in {city}, PA.")
    else:
        raise Exception("City field was empty in the API response.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        # C6: Top-level handler uses traceback.print_exc
        traceback.print_exc(file=sys.stderr)

