from Tools.Local_Business_Data.Search import Search

import traceback

# --- Constants ---
TARGET_BUSINESS_NAME = "Nonno's Bakery"

def get_bakery_search_results():
    """
    Searches for the business using the Search API.
    """
    try:
        # Rule 3: Construct correct inputs based on API_calling_code
        results = Search(query=TARGET_BUSINESS_NAME)
        return results
    except Exception as e:
        print(f"Error during business search: {e}")
        return None

def extract_state_from_results(search_data):
    """
    Analyzes search results to find the state of the target business.
    Rule 10: Use EXACT keys from response_schema ('data', 'state').
    """
    if not search_data or "data" not in search_data:
        return None

    businesses = search_data.get("data", [])
    if not businesses:
        return None

    # Rule 14: Lenient comparison for business name
    for business in businesses:
        name = business.get("name", "")
        if TARGET_BUSINESS_NAME.lower() in name.lower():
            # Rule 10: Extract 'state' verbatim from schema
            return business.get("state")

    # Fallback to first result if no strict name match but data exists
    return businesses[0].get("state")

def main():
    """
    Orchestrates the flow to find the state of Nonno's Bakery.
    """
    try:
        # Step 1: Search for the business
        search_results = get_bakery_search_results()

        if search_results is None:
            print("Could not retrieve search results.")
            return

        # Step 2: Extract the state from the data
        state = extract_state_from_results(search_results)

        if state:
            print(f"Nonno's Bakery is located in the state of: {state}")
        else:
            print("Could not find the state information for Nonno's Bakery.")

    except Exception:
        # Rule 9: Top-level exception handler printing full traceback to stderr
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
from pathlib import Path
