from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

# --- MODULE LEVEL CONSTANTS ---
TARGET_BUSINESS_NAME = "Perenn Bakery"
TARGET_LOCATION = "89511, Reno, NV"
REGION_CODE = "us"

def fetch_business_id():
    """
    Searches for the business using the target name and location to retrieve its business_id.
    """
    query = f"{TARGET_BUSINESS_NAME} {TARGET_LOCATION}"
    try:
        response = Search(query=query)
        if response.get("status") == "OK":
            data_list = response.get("data", [])
            if data_list:
                # Return the first matching business ID
                return data_list[0].get("business_id")
            else:
                print(f"No businesses found for query: {query}")
                return None
        else:
            print(f"Search API returned non-OK status: {response.get('status')}")
            return None
    except Exception as e:
        print(f"Error during Search API call: {e}")
        return None

def fetch_business_rating(business_id):
    """
    Retrieves the detailed profile of the business and extracts the star rating.
    """
    if not business_id:
        return None

    try:
        response = Business_Details(business_id=business_id, region=REGION_CODE)
        if response.get("status") == "OK":
            data_list = response.get("data", [])
            if data_list:
                business_info = data_list[0]
                # Extract 'rating' based on response_schema
                rating = business_info.get("rating")
                return rating
            else:
                print(f"No data found for business_id: {business_id}")
                return None
        else:
            print(f"Business_Details API returned non-OK status: {response.get('status')}")
            return None
    except Exception as e:
        print(f"Error during Business_Details API call: {e}")
        return None

def main():
    """
    Orchestrates the flow to find the star rating of the target bakery.
    """
    # Step 1: Find the business ID
    business_id = fetch_business_id()

    if business_id:
        # Step 2: Get the rating using the ID
        rating = fetch_business_rating(business_id)
        if rating is not None:
            print(f"The star rating of {TARGET_BUSINESS_NAME} in {TARGET_LOCATION} is: {rating}")
        else:
            print(f"Could not retrieve the star rating for {TARGET_BUSINESS_NAME}.")
    else:
        print(f"Could not find a business ID for {TARGET_BUSINESS_NAME} in {TARGET_LOCATION}.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

import sys
