from Tools.Maps_Data.Search import Search
from Tools.Maps_Data.Place_info import Place_info

import traceback

# --- Constants ---
TARGET_BUSINESS_NAME = "Red Mango"
TARGET_POSTAL_CODE = "19153"
TARGET_CITY = "Philadelphia"
TARGET_STATE = "PA"

def find_business_id():
    """
    Searches for the business using a combined query string and filters 
    the results based on the target name and location.
    """
    # Construct a query that includes name and location for better accuracy
    query_string = f"{TARGET_BUSINESS_NAME} {TARGET_POSTAL_CODE} {TARGET_CITY} {TARGET_STATE}"

    try:
        response = Search(query=query_string)
        data_list = response.get("data", [])

        if not data_list:
            return None

        # Iterate through results to find the best match based on schema keys
        for business in data_list:
            name = business.get("name", "")
            full_address = business.get("full_address", "")

            # Lenient comparison for name and postal code presence in address
            if (TARGET_BUSINESS_NAME.lower() in name.lower() and 
                TARGET_POSTAL_CODE in full_address):
                return business.get("business_id")

        # Fallback: return the first result if it looks like the business
        if data_list:
            return data_list[0].get("business_id")

    except Exception as e:
        print(f"Error during business search: {e}")
        return None

    return None

def get_business_rating(business_id):
    """
    Retrieves the rating for a specific business ID using Place_info.
    """
    if not business_id:
        return None

    try:
        response = Place_info(business_id=business_id)
        data_list = response.get("data", [])

        if data_list and len(data_list) > 0:
            # Extract 'rating' verbatim from response_schema
            return data_list[0].get("rating")

    except Exception as e:
        print(f"Error retrieving business rating: {e}")

    return None

def main():
    """
    Orchestrates the flow to find the star rating of the target business.
    """
    try:
        business_id = find_business_id()
        if not business_id:
            print(f"Could not find business ID for {TARGET_BUSINESS_NAME} in {TARGET_POSTAL_CODE}.")
            return

        rating = get_business_rating(business_id)
