    and extracts the business_id.
    """
    query = f"{TARGET_BUSINESS_NAME} {TARGET_LOCATION}"
    try:
        response = Search(query=query)
        if response.get("status") == "OK":
            data_list = response.get("data", [])
            for business in data_list:
                # Use lenient comparison for the name to ensure a match
                if TARGET_BUSINESS_NAME.lower() in business.get("name", "").lower():
                    return business.get("business_id")

