def get_total_review_count(business_id):
    """
    Retrieves the review count for the specified business.
    Note: The Search API already provides 'review_count' in its schema, 
    but the pseudocode specifically asks to use the Business_Reviews API.
    However, Business_Reviews returns a list of review objects.
    """
    if not business_id:
        return None

    try:
        response = Business_Reviews(business_id=business_id)
        if response.get("status") == "OK":
            reviews_data = response.get("data", [])
            # The Business_Reviews API returns a list of individual reviews.
            # To get the total count of reviews received, we count the length of the data list.
            return len(reviews_data)
        return None
    except Exception as e:
        print(f"Error retrieving reviews: {e}")
        return None

