            print(f"The number of reviews received by {TARGET_BUSINESS_NAME} in {TARGET_LOCATION} is: {review_count}")
        else:
            print(f"Could not retrieve review count for {TARGET_BUSINESS_NAME}.")

    except Exception:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

