import traceback

# --- Constants ---
TARGET_BUSINESS_NAME = "Philippine Smoked BBQ Grill"
TARGET_LOCATION = "postal code 19805, Wilmington, DE"
REGION_CODE = "us"

def find_business_id():
    """
    Searches for the business based on name and location to retrieve its business_id.
    """
    query = f"{TARGET_BUSINESS_NAME} in {TARGET_LOCATION}"
    try:
        response = Search(query=query)
        if response.get("status") == "OK":
            data = response.get("data", [])
            if data:
                # Return the first matching business ID
                return data[0].get("business_id")
            else:
                print(f"No business found for query: {query}")
                return None
        else:
            print(f"Search API returned non-OK status: {response.get('status')}")
            return None
    except Exception as e:
        print(f"Error during Search API call: {e}")
        return None

def check_appointment_requirement(business_id):
    """
    Retrieves business details and checks for appointment or reservation links.
    """
    try:
        response = Business_Details(business_id=business_id, region=REGION_CODE)
        if response.get("status") == "OK":
            data = response.get("data", [])
            if data:
                business_info = data[0]
                # Based on response_schema, we check booking_link and reservations_link
                booking_link = business_info.get("booking_link")
                reservations_link = business_info.get("reservations_link")

                if booking_link or reservations_link:
                    return {
                        "requires_appointment": "Likely/Available",
                        "booking_link": booking_link,
                        "reservations_link": reservations_link
                    }
                else:
                    return {
                        "requires_appointment": "No specific appointment link found",
                        "booking_link": None,
                        "reservations_link": None
                    }
            else:
                print(f"No details found for business_id: {business_id}")
                return None
        else:
            print(f"Business_Details API returned non-OK status: {response.get('status')}")
            return None
    except Exception as e:
        print(f"Error during Business_Details API call: {e}")
        return None

def main():
    """
    Orchestrates the flow to determine if the business requires an appointment.
    """
    print(f"Searching for: {TARGET_BUSINESS_NAME} in {TARGET_LOCATION}...")
    business_id = find_business_id()

    if not business_id:
        print("Could not find the business ID. Unable to determine appointment requirements.")
        return

    print(f"Found Business ID: {business_id}. Checking appointment details...")
    appointment_info = check_appointment_requirement(business_id)

    if appointment_info:
        status = appointment_info.get("requires_appointment")
        booking = appointment_info.get("booking_link")
        res = appointment_info.get("reservations_link")

        print("\n--- Result ---")
        print(f"Business: {TARGET_BUSINESS_NAME}")
        print(f"Appointment/Reservation Status: {status}")
        if booking:
            print(f"Booking Link: {booking}")
        if res:
            print(f"Reservations Link: {res}")
    else:
        print("Could not retrieve appointment information.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

