from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

# --- Constants ---
TARGET_BUSINESS_NAME = "Tacos Jalisco"
TARGET_CITY = "Reno"
TARGET_STATE = "NV"
TARGET_ZIP = "89502"
TARGET_REGION = "us"

def fetch_business_id():
    """
    Searches for the business using the provided name and location details
    to retrieve the business_id.
    """
    # Construct query string based on user requirement
    query = f"{TARGET_BUSINESS_NAME} {TARGET_CITY}, {TARGET_STATE} {TARGET_ZIP}"

    try:
        response = Search(query=query)
        if response.get("status") == "OK":
            data_list = response.get("data", [])
            if not data_list:
                print(f"No businesses found for query: {query}")
                return None

            # Find the best match based on name (lenient comparison)
            for business in data_list:
                name = business.get("name", "")
                if TARGET_BUSINESS_NAME.lower() in name.lower():
                    return business.get("business_id")

            # Fallback to first result if no strict name match but data exists
            return data_list[0].get("business_id")
        else:
            print(f"Search API returned non-OK status: {response.get('status')}")
            return None
    except Exception as e:
        print(f"Error during Search API call: {e}")
        return None

def fetch_business_categories(business_id):
    """
    Retrieves the business profile and extracts the categories (subtypes).
    """
    if not business_id:
        return None

    try:
        response = Business_Details(business_id=business_id, region=TARGET_REGION)
        if response.get("status") == "OK":
            data_list = response.get("data", [])
            if not data_list:
                print(f"No details found for business_id: {business_id}")
                return None

            business_info = data_list[0]
            # Based on response_schema, categories are in 'subtypes'
            categories = business_info.get("subtypes", [])
            return categories
        else:
            print(f"Business_Details API returned non-OK status: {response.get('status')}")
            return None
    except Exception as e:
        print(f"Error during Business_Details API call: {e}")
        return None

def main():
    """
    Orchestrates the flow to find the categories of the target business.
    """
    try:
        # Step 1: Find the business ID
        business_id = fetch_business_id()
        if not business_id:
            print(f"Could not find a business ID for {TARGET_BUSINESS_NAME}.")
            return

        # Step 2: Get categories using the ID
        categories = fetch_business_categories(business_id)

        if categories:
            print(f"The categories for {TARGET_BUSINESS_NAME} in {TARGET_CITY}, {TARGET_STATE} {TARGET_ZIP} are:")
            for cat in categories:
                print(f"- {cat}")
        else:
            print(f"No categories found for {TARGET_BUSINESS_NAME}.")

    except Exception:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

